(()=>{'use strict';const root=document.getElementById('bonga-subscriptions');if(!root)return;const buttons=[...root.querySelectorAll('[data-bonga-package]')],inputs=[...root.querySelectorAll('[data-bonga-product]')],status=root.querySelector('#bonga-subscription-status'),request=root.querySelector('#bonga-subscription-request');let tier=1;function selected(){return inputs.filter(x=>x.checked)}function render(){buttons.forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.bongaPackage)===tier)));if(tier===3){inputs.forEach(x=>{x.checked=true;x.disabled=true})}else{inputs.forEach(x=>x.disabled=false)}const names=selected().map(x=>x.value);status.textContent='Package 0'+tier+': '+(names.join(' + ')||'Select '+tier+' product'+(tier===1?'':'s'))+' ('+names.length+' of '+tier+').';request.disabled=names.length!==tier;}buttons.forEach(b=>b.addEventListener('click',()=>{tier=Number(b.dataset.bongaPackage);const current=selected();inputs.forEach((x,i)=>{x.checked=tier===3||current.includes(x)&&current.indexOf(x)<tier||(!current.length&&i<tier)});if(tier===2&&selected().length<2){inputs.find(x=>!x.checked).checked=true}render()}));inputs.forEach(x=>x.addEventListener('change',()=>{if(selected().length>tier){inputs.forEach(other=>{if(other!==x&&other.checked&&selected().length>tier)other.checked=false})}render()}));request.addEventListener('click',()=>{if(selected().length!==tier)return;const service='Bonga Bhengu App subscription — Package 0'+tier;const brief='I would like Package 0'+tier+' for the Bonga Bhengu App. Selected products: '+selected().map(x=>x.value).join(', ')+'. Please confirm monthly price, setup, inclusions and activation.';const form=document.getElementById('brief-form'),serviceInput=document.getElementById('brief-service'),goalInput=document.getElementById('brief-goal');if(form&&serviceInput&&goalInput){serviceInput.value=service;goalInput.value=brief;form.hidden=false;document.getElementById('brief-result')?.setAttribute('hidden','');document.getElementById('contact')?.scrollIntoView({behavior:'smooth',block:'start'});document.getElementById('brief-name')?.focus({preventScroll:true})}else{const url=new URL(location.href);url.hash='contact';location.href=url.href}});render()})();